<?php
namespace App\Http\Controllers\Api\V1; use App\Models\Provider; use App\Services\ProviderService; use Illuminate\Http\Request;
class ProviderController extends ApiController { public function __construct(private ProviderService $service){} public function index(Request $r){return $this->success($this->service->publicList($r->all()));} public function show(Provider $provider){abort_unless($provider->verification_status==='VERIFIED',404);return $this->success($provider->load(['user','category','media']));} public function profile(Request $r){return $this->success(Provider::where('user_id',$r->user()->id)->with(['category','media'])->firstOrFail());} public function update(Request $r){$p=Provider::where('user_id',$r->user()->id)->firstOrFail();$d=$r->validate(['bio'=>'sometimes|string|max:5000','experience_years'=>'sometimes|integer|min:0|max:100','location'=>'sometimes|string|max:255']);return $this->success($this->service->update($p,$d));} }
